msg.original = msg.payload;
const [plant, area, assetFromTopic] = msg.topic.split('/');
const p = msg.payload;
const errors = [];
const qualities = ['good', 'uncertain', 'bad'];
if (typeof p !== 'object' || p === null || Array.isArray(p)) {
    errors.push('payload is not a JSON object');
} else {
    if (p.asset_id !== assetFromTopic) errors.push('asset_id does not match topic');
    if (Number.isNaN(Date.parse(p.ts))) errors.push('ts is not a valid timestamp');
    if (!Array.isArray(p.signals)) {
        errors.push('signals is not a list');
    } else if (p.signals.length === 0) {
        errors.push('signals is empty');
    } else {
        const seen = new Set();
        p.signals.forEach((signal, index) => {
            const name = signal && typeof signal.name === 'string' ? signal.name : '';
            const label = name ? `signal ${name}` : `signal ${index + 1}`;
            if (!name) errors.push(`${label} has no name`);
            else if (seen.has(name)) errors.push(`${label} is duplicated`);
            else seen.add(name);
            if (!signal || typeof signal.value !== 'number' || !Number.isFinite(signal.value)) {
                errors.push(`${label} value is not a number`);
            }
            if (!signal || !qualities.includes(signal.quality)) {
                errors.push(`${label} quality is not good, uncertain or bad`);
            }
        });
    }
}
if (errors.length > 0) {
    msg.errors = errors;
    return [null, msg];
}
msg.reading = {
    time: p.ts,
    plant,
    area,
    asset_id: p.asset_id,
    signals: p.signals.map((signal) => ({
        name: signal.name,
        value: signal.value,
        quality: signal.quality
    }))
};
msg.payload = msg.reading;
msg.params = [p.asset_id];
return [msg, null];

const reading = msg.reading;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!reading) {
    msg.errors = ['reading missing before registry check'];
    return [null, msg];
}
if (rows.length === 0) {
    msg.payload = reading;
    msg.errors = ['asset_id is not in the asset registry'];
    return [null, msg];
}
const registered = rows[0];
if (registered.plant !== reading.plant || registered.area !== reading.area) {
    msg.payload = reading;
    msg.errors = ['plant or area does not match the asset registry'];
    return [null, msg];
}
msg.payload = reading;
return [msg, null];

const originalTopic = typeof msg.topic === 'string' ? msg.topic : '';
const body = Object.prototype.hasOwnProperty.call(msg, 'original') ? msg.original : msg.payload;
const stored = (body !== null && typeof body === 'object' && !Array.isArray(body))
    ? body
    : { unparsed: body === undefined ? null : String(body) };
const rejectedAt = new Date().toISOString();
msg.payload = {
    rejected_at: rejectedAt,
    topic: originalTopic,
    errors: msg.errors,
    payload: stored
};
msg.params = [rejectedAt, originalTopic, msg.errors, JSON.stringify(stored)];
return msg;

