const r = msg.payload;
msg.params = [r.time, r.plant, r.area, r.asset_id, r.temperature, r.pressure, r.vibration, r.quality];
return msg;

const reading = msg.reading;
const rows = Array.isArray(msg.payload) ? msg.payload : [];
if (!reading) {
    msg.errors = ['reading missing before limits check'];
    return [null, msg];
}
// The table is still wide. Accepted signals fold into that row until stage 3.
const WIDE = { bearing_temperature: 'temperature', vibration: 'vibration' };
const catalog = new Set(rows.map((row) => row.signal));
const unknown = [];
const storable = [];
const unstorable = [];
for (const signal of reading.signals) {
    if (!catalog.has(signal.name)) unknown.push(signal.name);
    else if (!Object.prototype.hasOwnProperty.call(WIDE, signal.name)) unstorable.push(signal.name);
    else storable.push(signal);
}
const errors = unknown.map((name) => `signal ${name} has no asset_limits row`);
for (const name of unstorable) {
    errors.push(`signal ${name} cannot be stored in the wide row`);
}
const qualities = new Set(storable.map((signal) => signal.quality));
if (storable.length > 0 && qualities.size > 1) {
    errors.push('signals do not share one quality');
    msg.errors = errors;
    return [null, msg];
}
if (storable.length === 0) {
    msg.errors = errors.length ? errors : ['signals is empty'];
    return [null, msg];
}
const row = {
    time: reading.time,
    plant: reading.plant,
    area: reading.area,
    asset_id: reading.asset_id,
    temperature: null,
    pressure: null,
    vibration: null,
    quality: storable[0].quality
};
for (const signal of storable) row[WIDE[signal.name]] = signal.value;
const insertMsg = Object.assign({}, msg, { payload: row });
delete insertMsg.errors;
if (errors.length === 0) return [insertMsg, null];
const rejectMsg = Object.assign({}, msg, { errors });
return [insertMsg, rejectMsg];
